`timescale 1ns/1ps
// Complete procedural 2.5D scene: no TF background dependency. Camera and guide move each frame.
// Exactly five pixel registers: R1 ground coords, R2 geometry,
// R3 class/font, R4 colour/alpha, R5 output. Host adds its original s6 register.
// Ground routes are clipped by the projected building prisms.
module emergency_map_top #(
 parameter integer REMOTE_MAP=0,RASTER_STEP=1,RASTER_VGA=0,ARCHITECTURE_DETAILS=1,
 parameter integer SCREEN_W=1280, SCREEN_H=720,
 parameter integer MAP_XP0=0, MAP_XP1=100, MAP_YP0=0, MAP_YP1=100
)(
 input wire clk,rst,active,
 input wire [2:0] state,
 input wire [1:0] event_type,
 input wire remote_live,input wire [187:0] remote_scene,
 input wire blink_on,frame_tick,
 input wire [11:0] cx,cy,
 output reg [23:0] map_rgb,
 output reg [7:0] map_alpha
);
// The asset/overlay contract is 1280x720. Other output modes require new assets.
reg [4:0] flow; reg [3:0] pulse;
reg [8:0] camera_clock;
reg [10:0] walk;
wire [6:0] camera_phase=camera_clock[8:2];
wire [5:0] camera_triangle=camera_phase[6] ? ~camera_phase[5:0] : camera_phase[5:0];
wire signed [11:0] camera_x=$signed({9'd0,camera_triangle})-12'sd32;
wire signed [11:0] camera_y=camera_x>>>2;
reg [1:0] event_q; reg backup_q;
reg m0ax,m1ax,b0ax,b1ax,m0dir,m1dir,b0dir,b1dir;
reg [10:0] m0u,m0v,m0len,m1u,m1v,m1len,b0u,b0v,b0len,b1u,b1v,b1len;
reg [10:0] hu0,hv0,hu1,hv1,hz,su0,sv0,su1,sv1;
reg [11:0] px,py,ax,ay,mx,my,bx,by;
always @(posedge clk or posedge rst) begin
 if(rst) begin
  flow<=0;pulse<=4;event_q<=0;backup_q<=0;
  m0ax<=0;m1ax<=0;b0ax<=0;b1ax<=0;m0dir<=0;m1dir<=0;b0dir<=0;b1dir<=0;
  m0u<=0;m0v<=0;m0len<=0;m1u<=0;m1v<=0;m1len<=0;
  b0u<=0;b0v<=0;b0len<=0;b1u<=0;b1v<=0;b1len<=0;
  hu0<=0;hv0<=0;hu1<=0;hv1<=0;hz<=0;su0<=0;sv0<=0;su1<=0;sv1<=0;
  px<=0;py<=0;ax<=0;ay<=0;mx<=0;my<=0;bx<=0;by<=0;
 end else if(!active) begin flow<=0;pulse<=4;backup_q<=0; end
 else if(frame_tick) begin
  flow<=(event_q!=event_type)?0:flow+1'b1;
  pulse<=(event_q!=event_type || pulse==15)?4:pulse+1'b1;
  event_q<=event_type;backup_q<=(state==3);
  case(event_type)
   // BEGIN GENERATED isometric_plan.vh
2'd0: begin
    m0ax <= 1'd1;
    m0dir <= 1'd0;
    m0u <= 11'd80;
    m0v <= 11'd432;
    m0len <= 11'd176;
    m1ax <= 1'd0;
    m1dir <= 1'd1;
    m1u <= 11'd80;
    m1v <= 11'd256;
    m1len <= 11'd432;
    b0ax <= 1'd0;
    b0dir <= 1'd1;
    b0u <= 11'd80;
    b0v <= 11'd432;
    b0len <= 11'd176;
    b1ax <= 1'd1;
    b1dir <= 1'd1;
    b1u <= 11'd256;
    b1v <= 11'd432;
    b1len <= 11'd80;
    hu0 <= 11'd112;
    hv0 <= 11'd304;
    hu1 <= 11'd208;
    hv1 <= 11'd388;
    hz <= 11'd50;
    su0 <= 11'd70;
    sv0 <= 11'd250;
    su1 <= 11'd95;
    sv1 <= 11'd340;
    px <= 12'd288;
    py <= 12'd382;
    ax <= 12'd454;
    ay <= 12'd341;
    mx <= 12'd896;
    my <= 12'd534;
    bx <= 12'd384;
    by <= 12'd534;
end
2'd1: begin
    m0ax <= 1'd0;
    m0dir <= 1'd1;
    m0u <= 11'd80;
    m0v <= 11'd80;
    m0len <= 11'd176;
    m1ax <= 1'd1;
    m1dir <= 1'd0;
    m1u <= 11'd256;
    m1v <= 11'd80;
    m1len <= 11'd80;
    b0ax <= 1'd1;
    b0dir <= 1'd1;
    b0u <= 11'd80;
    b0v <= 11'd80;
    b0len <= 11'd176;
    b1ax <= 1'd0;
    b1dir <= 1'd0;
    b1u <= 11'd80;
    b1v <= 11'd256;
    b1len <= 11'd80;
    hu0 <= 11'd112;
    hv0 <= 11'd112;
    hu1 <= 11'd208;
    hv1 <= 11'd196;
    hz <= 11'd52;
    su0 <= 11'd150;
    sv0 <= 11'd68;
    su1 <= 11'd220;
    sv1 <= 11'd92;
    px <= 12'd640;
    py <= 12'd206;
    ax <= 12'd646;
    ay <= 12'd243;
    mx <= 12'd896;
    my <= 12'd278;
    bx <= 12'd384;
    by <= 12'd278;
end
2'd2: begin
    m0ax <= 1'd1;
    m0dir <= 1'd1;
    m0u <= 11'd432;
    m0v <= 11'd80;
    m0len <= 11'd176;
    m1ax <= 1'd0;
    m1dir <= 1'd1;
    m1u <= 11'd432;
    m1v <= 11'd256;
    m1len <= 11'd80;
    b0ax <= 1'd0;
    b0dir <= 1'd0;
    b0u <= 11'd432;
    b0v <= 11'd80;
    b0len <= 11'd176;
    b1ax <= 1'd1;
    b1dir <= 1'd0;
    b1u <= 11'd256;
    b1v <= 11'd80;
    b1len <= 11'd80;
    hu0 <= 11'd304;
    hv0 <= 11'd112;
    hu1 <= 11'd400;
    hv1 <= 11'd196;
    hz <= 11'd56;
    su0 <= 11'd420;
    sv0 <= 11'd160;
    su1 <= 11'd445;
    sv1 <= 11'd230;
    px <= 12'd992;
    py <= 12'd382;
    ax <= 12'd838;
    ay <= 12'd335;
    mx <= 12'd896;
    my <= 12'd534;
    bx <= 12'd896;
    by <= 12'd278;
end
2'd3: begin
    m0ax <= 1'd0;
    m0dir <= 1'd0;
    m0u <= 11'd432;
    m0v <= 11'd432;
    m0len <= 11'd176;
    m1ax <= 1'd1;
    m1dir <= 1'd0;
    m1u <= 11'd256;
    m1v <= 11'd432;
    m1len <= 11'd176;
    b0ax <= 1'd1;
    b0dir <= 1'd0;
    b0u <= 11'd432;
    b0v <= 11'd432;
    b0len <= 11'd176;
    b1ax <= 1'd0;
    b1dir <= 1'd0;
    b1u <= 11'd432;
    b1v <= 11'd256;
    b1len <= 11'd176;
    hu0 <= 11'd304;
    hv0 <= 11'd304;
    hu1 <= 11'd400;
    hv1 <= 11'd388;
    hz <= 11'd58;
    su0 <= 11'd330;
    sv0 <= 11'd420;
    su1 <= 11'd400;
    sv1 <= 11'd445;
    px <= 12'd640;
    py <= 12'd558;
    ax <= 12'd646;
    ay <= 12'd429;
    mx <= 12'd640;
    my <= 12'd406;
    bx <= 12'd640;
    by <= 12'd406;
end
// END GENERATED isometric_plan.vh
  endcase
 end
end
wire a0ax=backup_q?b0ax:m0ax, a1ax=backup_q?b1ax:m1ax;
wire a0dir=backup_q?b0dir:m0dir, a1dir=backup_q?b1dir:m1dir;
wire [10:0] a0u=backup_q?b0u:m0u, a0v=backup_q?b0v:m0v,a0len=backup_q?b0len:m0len;
wire [10:0] a1u=backup_q?b1u:m1u, a1v=backup_q?b1v:m1v,a1len=backup_q?b1len:m1len;
wire [11:0] ex=backup_q?bx:mx, ey=backup_q?by:my;
always @(posedge clk or posedge rst)
 if(rst)begin camera_clock<=0;walk<=0;end
 else if(!active)begin camera_clock<=0;walk<=0;end
 else if(frame_tick)begin
  camera_clock<=camera_clock+1'b1;
  if(event_q!=event_type || backup_q!=(state==3) || walk+11'd2>=a0len+a1len)walk<=0;
  else walk<=walk+11'd2;
 end


wire second_segment=walk>=a0len;
wire [10:0] walk_t=second_segment?(walk-a0len):walk;
wire walk_axis=second_segment?a1ax:a0ax, walk_dir=second_segment?a1dir:a0dir;
wire [10:0] walk_u0=second_segment?a1u:a0u,walk_v0=second_segment?a1v:a0v;
wire [10:0] walk_u=walk_axis?walk_u0:(walk_dir?walk_u0+walk_t:walk_u0-walk_t);
wire [10:0] walk_v=!walk_axis?walk_v0:(walk_dir?walk_v0+walk_t:walk_v0-walk_t);
wire [11:0] guide_x=12'd640+{1'b0,walk_u}-{1'b0,walk_v};
wire [11:0] guide_y=12'd136+(({1'b0,walk_u}+{1'b0,walk_v})>>1);
// BEGIN FULLSCREEN VIEWPORT
wire [13:0] view_x3={2'b0,cx}+{1'b0,cx,1'b0};
wire [13:0] view_y3={2'b0,cy}+{1'b0,cy,1'b0};
wire signed [11:0] scaled_x=$signed({2'b0,view_x3[13:2]});
wire signed [11:0] scaled_y=$signed({2'b0,view_y3[13:2]});
wire signed [11:0] view_x=12'sd160+scaled_x;
wire signed [11:0] view_y=12'sd134+scaled_y;
wire use_remote=REMOTE_MAP && remote_live;
wire signed [11:0] scene_x,scene_y;
generate if(REMOTE_MAP)begin:distributed_view
 wire signed [23:0] local_x=($signed(24'sd160)-camera_x)<<<12;
 wire signed [23:0] local_y=($signed(24'sd134)-camera_y)<<<12;
 map_view_raster #(.PIXEL_STEP(RASTER_STEP),.ROW_SCALE_3_2(RASTER_VGA)) u_view(.clk(clk),.rst(rst),.cx(cx),.cy(cy),
  .origin_x(use_remote?$signed(remote_scene[55:32]):local_x),
  .origin_y(use_remote?$signed(remote_scene[79:56]):local_y),
  .step(use_remote?remote_scene[91:80]:12'd3072),.scene_x(scene_x),.scene_y(scene_y));
end else begin:original_view
 assign scene_x=view_x-camera_x;assign scene_y=view_y-camera_y;
end endgenerate
// Camera offsets settle in blanking; no camera subtraction in the ground pixel path.
reg signed [11:0] ground_u_bias,ground_v_bias;
always @(posedge clk or posedge rst)
 if(rst)begin ground_u_bias<=-12'sd512;ground_v_bias<=12'sd448;end
 else begin
  ground_u_bias<=REMOTE_MAP?-12'sd940:(-12'sd512-camera_x-(camera_y<<<1));
  ground_v_bias<=REMOTE_MAP?12'sd340:(12'sd448+camera_x-(camera_y<<<1));
 end
wire signed [11:0] ground_sum=REMOTE_MAP?(scene_x+(scene_y<<<1)):(scaled_x+(scaled_y<<<1));
wire signed [11:0] ground_difference=REMOTE_MAP?((scene_y<<<1)-scene_x):((scaled_y<<<1)-scaled_x);
// END FULLSCREEN VIEWPORT
// Frame-static projection settles during vertical blanking, outside the pixel distance path.
reg [11:0] guide_screen_x,guide_screen_y,incident_screen_x,incident_screen_y,exit_screen_x,exit_screen_y;
reg [11:0] local_guide_x,local_guide_y;
always @(posedge clk or posedge rst)
 if(rst)begin local_guide_x<=0;local_guide_y<=0;end
 else begin local_guide_x<=guide_x;local_guide_y<=guide_y;end
always @(posedge clk or posedge rst)
 if(rst)begin guide_screen_x<=0;guide_screen_y<=0;incident_screen_x<=0;incident_screen_y<=0;exit_screen_x<=0;exit_screen_y<=0;end
 else begin
  guide_screen_x<=guide_x+camera_x-12'd160;guide_screen_y<=guide_y+camera_y-12'd134;
  incident_screen_x<=ax+camera_x-12'd160;incident_screen_y<=ay+camera_y-12'd134;
  exit_screen_x<=ex+camera_x-12'd160;exit_screen_y<=ey+camera_y-12'd134;
 end
reg signed [12:0] person_dx1,person_dy1,incident_dx1,incident_dy1,exit_dx1,exit_dy1;
always @(posedge clk or posedge rst)
 if(rst)begin person_dx1<=0;person_dy1<=0;incident_dx1<=0;incident_dy1<=0;exit_dx1<=0;exit_dy1<=0;end
 else begin
  person_dx1<=REMOTE_MAP?($signed(scene_x)-$signed({1'b0,(use_remote?remote_scene[151:140]:local_guide_x)})):($signed(scaled_x)-$signed({1'b0,guide_screen_x}));
  person_dy1<=REMOTE_MAP?($signed(scene_y)-$signed({1'b0,(use_remote?remote_scene[163:152]:local_guide_y)})):($signed(scaled_y)-$signed({1'b0,guide_screen_y}));
  incident_dx1<=REMOTE_MAP?($signed(scene_x)-$signed({1'b0,ax})):($signed(scaled_x)-$signed({1'b0,incident_screen_x}));
  incident_dy1<=REMOTE_MAP?($signed(scene_y)-$signed({1'b0,ay})):($signed(scaled_y)-$signed({1'b0,incident_screen_y}));
  exit_dx1<=REMOTE_MAP?($signed(scene_x)-$signed({1'b0,(use_remote?remote_scene[175:164]:ex)})):($signed(scaled_x)-$signed({1'b0,exit_screen_x}));
  exit_dy1<=REMOTE_MAP?($signed(scene_y)-$signed({1'b0,(use_remote?remote_scene[187:176]:ey)})):($signed(scaled_y)-$signed({1'b0,exit_screen_y}));
 end
// R1. Signed 12-bit projection covers the full 1280x720 viewport and camera travel; blanking is clipped by valid1.
wire signed [11:0] dx=scene_x-12'sd640;
wire signed [11:0] yy=(scene_y-12'sd150)<<<1;
reg signed [11:0] gu,gv;
reg [11:0] x1,y1,sx1,sy1;reg valid1;
always @(posedge clk or posedge rst)
 if(rst)begin gu<=0;gv<=0;x1<=0;y1<=0;sx1<=0;sy1<=0;valid1<=0;end
 else begin gu<=(ground_sum+ground_u_bias)>>>1;gv<=(ground_difference+ground_v_bias)>>>1;x1<=cx;y1<=cy;sx1<=scene_x[11:0];sy1<=scene_y[11:0];
  valid1<=active && cx<1280 && cy<720;end
// BEGIN GENERATED isometric_occlusion.vh
wire occ0 = (gu >= 12'sd60) && (gu <= 12'sd208) &&
 (gv >= 12'sd60) && (gv <= 12'sd196) &&
 ((gu-gv) <= 12'sd96) && ((gv-gu) <= 12'sd84);
wire occ1 = (gu >= 12'sd248) && (gu <= 12'sd400) &&
 (gv >= 12'sd56) && (gv <= 12'sd196) &&
 ((gu-gv) <= 12'sd288) && ((gv-gu) <= -12'sd108);
wire occ2 = (gu >= 12'sd62) && (gu <= 12'sd208) &&
 (gv >= 12'sd254) && (gv <= 12'sd388) &&
 ((gu-gv) <= -12'sd96) && ((gv-gu) <= 12'sd276);
wire occ3 = (gu >= 12'sd246) && (gu <= 12'sd400) &&
 (gv >= 12'sd246) && (gv <= 12'sd388) &&
 ((gu-gv) <= 12'sd96) && ((gv-gu) <= 12'sd84);
wire occ4 = (gu >= 12'sd272) && (gu <= 12'sd398) &&
 (gv >= -12'sd10) && (gv <= 12'sd54) &&
 ((gu-gv) <= 12'sd378) && ((gv-gu) <= -12'sd248);
wire occ5 = (gu >= -12'sd18) && (gu <= 12'sd54) &&
 (gv >= 12'sd264) && (gv <= 12'sd386) &&
 ((gu-gv) <= -12'sd248) && ((gv-gu) <= 12'sd366);
wire occ6 = (gu >= 12'sd424) && (gu <= 12'sd492) &&
 (gv >= 12'sd270) && (gv <= 12'sd388) &&
 ((gu-gv) <= 12'sd188) && ((gv-gu) <= -12'sd70);
wire occluded = occ0 || occ1 || occ2 || occ3 || occ4 || occ5 || occ6;
// END GENERATED isometric_occlusion.vh
function [11:0] abs12; input signed [11:0] a;begin abs12=a[11]?-a:a;end endfunction
// BEGIN SPECIALIZED ROUTES
reg live0,live1,rim0,rim1,dead0,dead1;reg [4:0] along0,along1;reg [3:0] across0,across1;
reg [15:0] fallback_route,fallback_dirs,fallback_dead;
always @* begin
 fallback_route=0;fallback_dirs=0;fallback_dead=0;
 case({event_q,backup_q})
  0:begin fallback_route=16'h408c;fallback_dirs=16'h400c;end
  1:begin fallback_route=16'h8010;fallback_dirs=16'h8010;fallback_dead=16'h408c;end
  2:begin fallback_route=16'h1001;fallback_dirs=16'h0001;end
  3:begin fallback_route=16'h2040;fallback_dirs=16'h0040;fallback_dead=16'h1001;end
  4:begin fallback_route=16'h4400;fallback_dirs=16'h4400;end
  5:begin fallback_route=16'h1002;fallback_dirs=0;fallback_dead=16'h4400;end
  6:begin fallback_route=16'h0220;fallback_dirs=0;end
  7:begin fallback_route=16'h0808;fallback_dirs=0;fallback_dead=16'h0220;end
 endcase
end
wire [15:0] selected_route=use_remote?remote_scene[107:92]:fallback_route;
wire [15:0] selected_dirs=use_remote?remote_scene[123:108]:fallback_dirs;
wire [15:0] selected_dead=use_remote?remote_scene[139:124]:fallback_dead;
wire hr0=(gv>=71)&&(gv<=89),hr1=(gv>=247)&&(gv<=265),hr2=(gv>=423)&&(gv<=441);
wire vc0=(gu>=71)&&(gu<=89),vc1=(gu>=247)&&(gu<=265),vc2=(gu>=423)&&(gu<=441);
wire [3:0] he=hr0?((gu<256)?4'd0:4'd1):hr2?((gu<256)?4'd4:4'd5):
 ((gu<80)?4'd13:(gu>432)?4'd14:(gu<256)?4'd2:4'd3);
wire [3:0] ve=vc0?((gv<256)?4'd6:4'd7):vc2?((gv<256)?4'd10:4'd11):
 ((gv<80)?4'd12:(gv>432)?4'd15:(gv<256)?4'd8:4'd9);
wire hspan=((hr0||hr2)&&(gu>=80)&&(gu<=432))||(hr1&&(gu>=0)&&(gu<=512));
wire vspan=((vc0||vc2)&&(gv>=80)&&(gv<=432))||(vc1&&(gv>=0)&&(gv<=512));
wire hlive=(gv[3:0]<=6)||(gv[3:0]>=10),vlive=(gu[3:0]<=6)||(gu[3:0]>=10);
wire hdead=(gv[3:0]<=5)||(gv[3:0]>=11),vdead=(gu[3:0]<=5)||(gu[3:0]>=11);
generate if(REMOTE_MAP)begin:graph_lanes
always @* begin
 rim0=hspan && selected_route[he];rim1=vspan && selected_route[ve];
 live0=rim0&&hlive;live1=rim1&&vlive;
 dead0=hspan&&selected_dead[he]&&hdead;dead1=vspan&&selected_dead[ve]&&vdead;
 along0=selected_dirs[he]?(gu[4:0]-5'd16):(5'd16-gu[4:0]);
 along1=selected_dirs[ve]?(gv[4:0]-5'd16):(5'd16-gv[4:0]);
 across0=gv[3]?(-gv[3:0]):gv[3:0];across1=gu[3]?(-gu[3:0]):gu[3:0];
end
end else begin:original_lanes
always @(*)begin live0=0;live1=0;rim0=0;rim1=0;dead0=0;dead1=0;along0=0;along1=0;across0=0;across1=0;
case({event_q,backup_q})
3'd0:begin
 live0=(gv>=256)&&(gv<=432)&&(gu>=74)&&(gu<=86);rim0=(gv>=256)&&(gv<=432)&&(gu>=71)&&(gu<=89);
 along0=5'd16-gv[4:0];across0=gu[3:0]-4'd0;if(across0[3])across0=-across0;
 live1=(gu>=80)&&(gu<=512)&&(gv>=250)&&(gv<=262);rim1=(gu>=80)&&(gu<=512)&&(gv>=247)&&(gv<=265);
 along1=gu[4:0]-5'd16;across1=gv[3:0]-4'd0;if(across1[3])across1=-across1;
end
3'd1:begin
 live0=(gu>=80)&&(gu<=256)&&(gv>=426)&&(gv<=438);rim0=(gu>=80)&&(gu<=256)&&(gv>=423)&&(gv<=441);
 along0=gu[4:0]-5'd16;across0=gv[3:0]-4'd0;if(across0[3])across0=-across0;
 live1=(gv>=432)&&(gv<=512)&&(gu>=250)&&(gu<=262);rim1=(gv>=432)&&(gv<=512)&&(gu>=247)&&(gu<=265);
 along1=gv[4:0]-5'd16;across1=gu[3:0]-4'd0;if(across1[3])across1=-across1;
 dead0=(gv>=256)&&(gv<=432)&&(gu>=75)&&(gu<=85);
 dead1=(gu>=80)&&(gu<=512)&&(gv>=251)&&(gv<=261);
end
3'd2:begin
 live0=(gu>=80)&&(gu<=256)&&(gv>=74)&&(gv<=86);rim0=(gu>=80)&&(gu<=256)&&(gv>=71)&&(gv<=89);
 along0=gu[4:0]-5'd16;across0=gv[3:0]-4'd0;if(across0[3])across0=-across0;
 live1=(gv>=0)&&(gv<=80)&&(gu>=250)&&(gu<=262);rim1=(gv>=0)&&(gv<=80)&&(gu>=247)&&(gu<=265);
 along1=5'd16-gv[4:0];across1=gu[3:0]-4'd0;if(across1[3])across1=-across1;
end
3'd3:begin
 live0=(gv>=80)&&(gv<=256)&&(gu>=74)&&(gu<=86);rim0=(gv>=80)&&(gv<=256)&&(gu>=71)&&(gu<=89);
 along0=gv[4:0]-5'd16;across0=gu[3:0]-4'd0;if(across0[3])across0=-across0;
 live1=(gu>=0)&&(gu<=80)&&(gv>=250)&&(gv<=262);rim1=(gu>=0)&&(gu<=80)&&(gv>=247)&&(gv<=265);
 along1=5'd16-gu[4:0];across1=gv[3:0]-4'd0;if(across1[3])across1=-across1;
 dead0=(gu>=80)&&(gu<=256)&&(gv>=75)&&(gv<=85);
 dead1=(gv>=0)&&(gv<=80)&&(gu>=251)&&(gu<=261);
end
3'd4:begin
 live0=(gv>=80)&&(gv<=256)&&(gu>=426)&&(gu<=438);rim0=(gv>=80)&&(gv<=256)&&(gu>=423)&&(gu<=441);
 along0=gv[4:0]-5'd16;across0=gu[3:0]-4'd0;if(across0[3])across0=-across0;
 live1=(gu>=432)&&(gu<=512)&&(gv>=250)&&(gv<=262);rim1=(gu>=432)&&(gu<=512)&&(gv>=247)&&(gv<=265);
 along1=gu[4:0]-5'd16;across1=gv[3:0]-4'd0;if(across1[3])across1=-across1;
end
